// Детектор «разговора не было». Одна функция на две ноды: agent-facts-assembler и b4.5,
// по образцу isAiComment — детерминированная, без обращений к сети и модели.
//
// Зачем. Транскрипт приписывает клиенту любой голос на той стороне. Если ответил
// автоответчик оператора, виртуальный помощник или человек сказал только «алло», в фактах
// появляется реплика с actor=client, и судья считает это контактом с клиентом. На живой
// сделке 119215 из двух таких звонков (11 и 6 секунд) вышел вердикт «неправомерен, закрыли
// при доступном клиенте» и ложная ошибка «причина "не выходит на связь" не соответствует фактам».
//
// Существующий detectVoicemail в agent-facts-assembler ловит часть случаев, но его списки
// не покрывают фразы операторов связи («продолжаем дозваниваться, оставайтесь на линии»),
// виртуальных помощников («я виртуальный ассистент») и пустые приветствия.
// Этот детектор — второй слой, он добирает остальное.

// ── константы ───────────────────────────────────────────────────────────────

// Выше этой длительности разговор считаем состоявшимся и детектор не применяем.
var NOTALK_MAX_SEC = 20;

// Остаток текста после вырезания приветствий: больше этого — значит что-то содержательное сказали.
var NOTALK_MEANINGFUL_CHARS = 12;

// Порог для ветки с машиной. Там после вырезания фраз автоответчика остаются обрывки
// («абонент», «его телефон», «если хотите»), поэтому порог выше: содержательной считаем
// только заметную живую реплику.
var NOTALK_MACHINE_REST_CHARS = 40;

// Фразы систем дозвона. Звучат ДО того, как трубку сняли, поэтому сами по себе ничего не
// значат: после них мог ответить и настоящий клиент. Вырезаются как шум.
var NOTALK_DIALING = [
  'оставайтесь на линии', 'продолжаем дозваниваться', 'продолжаю дозвон', 'должны дозваниваться',
  'дозваниваться до абонента', 'ожидайте ответа', 'не отключайтесь', 'продолжаю вызов'
];

// Фразы, которые может произнести только машина или чужой человек, но не клиент по своей сделке.
// Если такая фраза есть и клиент больше ничего не сказал — разговора не было независимо от того,
// успел ли менеджер назвать цель: он говорил с автоответчиком или секретарём.
// Составлены по фактическим транскриптам 1591 короткого звонка.
var NOTALK_MACHINE = [
  // абонент недоступен
  'абонент сейчас не может ответить', 'абонент не может ответить', 'абонент пока не может',
  'абонент пока не берет трубку', 'абонент не берет трубку', 'абонент недоступен',
  'абонент не доступен', 'абонент временно недоступен', 'абонент сейчас не на связи',
  'абонент занят', 'абонент сейчас никак не', 'абонент сейчас не в сети',
  'линия абонента сейчас занята', 'линия абонента занята', 'номер абонента занят',
  'вызываемый не может ответить', 'вызываемый абонент', 'вам не могут ответить', 'не могут ответить',
  'тот кому вы звоните не отвечает', 'попросите его перезвонить',
  // подсказки оператора связи в конце записи
  'попробуйте перезвонить', 'перезвонить позднее', 'вне зоны действия',
  'телефон выключен', 'телефон разряжен', 'бесплатное смс', 'отправить бесплатное',
  'не молчите',
  'не может ответить', 'не в сети', 'неудобно разговаривать', 'перенаправлен на',
  // автоответчики и голосовые помощники. Проверено на выгрузке: слова «ассистент»,
  // «помощник» и «голосовой» в коротких звонках встречаются только у роботов (62, 34 и 74 раза).
  'автоответчик', 'ассистент', 'помощник', 'помошник', 'секретарь',
  'почтовый ящик', 'голосовой',
  'передам ему ваше сообщение', 'передам ваше сообщение', 'передам сообщение',
  'сохраню и передам', 'все от вас передам', 'что передать', 'что нужно передать',
  'оставьте сообщение', 'оставить сообщение', 'после сигнала', 'после звукового сигнала',
  'запишу ваше сообщение', 'в тоновом режиме', 'в тональном режиме', 'для соединения нажмите',
  // робот спрашивает цель звонка вместо клиента
  'с какой целью звоните', 'с какой целью', 'по какому поводу вы звоните',
  'озвучьте что', 'скажите что нужно',
  // просьба перезвонить от системы
  'вам перезвонить', 'перезвоните позже пожалуйста'
];

// Пустые реплики: приветствия и подтверждения, из которых нельзя понять, что клиент
// включился в разговор. Вырезаются из текста как отдельные фразы.
var NOTALK_GREETING = [
  // Системный префикс телефонии: встречается в 356 коротких звонках, сам по себе ничего
  // не говорит о разговоре. Вырезаем, чтобы остаток показал, был ли разговор по существу.
  'запись разговоров активирована', 'запись разговора активирована', 'запись разговоров',
  'алло', 'аллло', 'ало', 'здравствуйте', 'здрасьте', 'приветствую', 'привет',
  'продолжайте', 'на связи',
  'добрый день', 'добрый вечер', 'доброе утро', 'добрый',
  'я вас слушаю', 'слушаю вас', 'слушаю', 'говорите пожалуйста', 'говорите',
  'по какому вопросу звоните', 'по какому вопросу', 'по какому поводу', 'кто это',
  'да да да', 'да да', 'да', 'нет', 'ага', 'угу', 'ммм', 'мм', 'э', 'а', 'ну',
  'пожалуйста', 'спасибо', 'что', 'простите', 'извините', 'секунду', 'минуту'
];

// Слова, по которым видно, что менеджер назвал цель звонка. Если назвал — считаем, что
// он успел донести предложение, и звонок детектором не помечаем.
var NOTALK_PURPOSE = [
  'окн', 'остекл', 'балкон', 'двер', 'лодж', 'перегород', 'витраж',
  'замер', 'расчет', 'смет', 'стоимост', 'цена', 'цены', 'монтаж', 'установк',
  'динал', 'завод', 'заявк', 'заказ', 'договор', 'предложени', 'акци', 'скидк',
  'уточнить', 'напомнить', 'подтвердить', 'согласовать', 'отправил', 'отправля',
  'звоню по', 'звоню из', 'меня зовут', 'вас беспокоит', 'вам удобно'
];

// ── функция ─────────────────────────────────────────────────────────────────

function notalkNormalize(text) {
  if (!text) return '';
  return String(text)
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[.,!?;:()"«»\-–—'"]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Остаток текста после вырезания приветствий. Длинные фразы вырезаем первыми,
// иначе «слушаю» съест часть «я вас слушаю» и оставит мусор.
function notalkStripGreetings(norm) {
  var sorted = NOTALK_GREETING.slice().sort(function (a, b) { return b.length - a.length; });
  var rest = ' ' + norm + ' ';
  for (var i = 0; i < sorted.length; i++) {
    var needle = ' ' + sorted[i] + ' ';
    while (rest.indexOf(needle) !== -1) rest = rest.split(needle).join(' ');
  }
  return rest.replace(/\s+/g, ' ').trim();
}

function notalkMachineHit(norm) {
  for (var i = 0; i < NOTALK_MACHINE.length; i++) {
    if (norm.indexOf(NOTALK_MACHINE[i]) !== -1) return NOTALK_MACHINE[i];
  }
  return null;
}

// Вырезает фразы систем дозвона: они звучат до ответа и о разговоре ничего не говорят.
function notalkStripDialing(norm) {
  var rest = ' ' + norm + ' ';
  for (var i = 0; i < NOTALK_DIALING.length; i++) {
    while (rest.indexOf(NOTALK_DIALING[i]) !== -1) rest = rest.split(NOTALK_DIALING[i]).join(' ');
  }
  return rest.replace(/\s+/g, ' ').trim();
}

function notalkManagerNamedPurpose(norm) {
  for (var i = 0; i < NOTALK_PURPOSE.length; i++) {
    if (norm.indexOf(NOTALK_PURPOSE[i]) !== -1) return NOTALK_PURPOSE[i];
  }
  return false;
}

// Возвращает null, если разговор состоялся, либо объект с причиной.
function detectNoConversation(clientText, managerText, durationSec) {
  if (typeof durationSec !== 'number' || durationSec > NOTALK_MAX_SEC) return null;

  // Сначала убираем шум систем дозвона — он звучит до ответа.
  var cn = notalkStripDialing(notalkNormalize(clientText));
  var mn = notalkNormalize(managerText);

  // Фразу машины ищем в обеих репликах: транскрипт иногда приписывает её менеджеру
  // (диаризация путает стороны, когда менеджер молчит).
  var machine = notalkMachineHit(cn) || notalkMachineHit(mn);
  var rest = notalkStripGreetings(cn);
  var onlyGreeting = rest.length <= NOTALK_MEANINGFUL_CHARS;

  // Сторона клиента сказала что-то своё — разговор был, не помечаем.
  if (!machine && !onlyGreeting) return null;

  // Ответила машина или чужой человек, и больше ничего не сказано: разговора с клиентом
  // не было, даже если менеджер успел назвать цель — он говорил с автоответчиком.
  if (machine) {
    var restNoMachine = rest;
    for (var mi = 0; mi < NOTALK_MACHINE.length; mi++) {
      restNoMachine = restNoMachine.split(NOTALK_MACHINE[mi]).join(' ');
    }
    restNoMachine = restNoMachine.replace(/\s+/g, ' ').trim();
    if (restNoMachine.length <= NOTALK_MACHINE_REST_CHARS) {
      return { reason: 'machine', matched: machine, rest: restNoMachine, duration_sec: durationSec };
    }
    // После машины клиент всё же сказал что-то по существу — разговор был.
    return null;
  }

  // Клиент ограничился приветствием. Если менеджер успел назвать цель, считаем это контактом:
  // клиент снял трубку и услышал предложение. Если менеджер молчал — звонок сорвался у нас.
  var purpose = notalkManagerNamedPurpose(mn);
  if (purpose) return null;

  return { reason: 'greeting_only', matched: null, rest: rest, duration_sec: durationSec };
}
